pub broadcast proof fn lemma_seq_empty<A>()
    ensures
        #[trigger] Seq::<A>::empty().len() == 0,
{
    let s = Seq::<A>::empty();
    match s.inner {
        SeqInner::Nil => {
            assert(s == Seq { inner: SeqInner::Nil });
        },
        SeqInner::Cons { tail, .. } => {
            let seq_tail = Seq { inner: tail@ };
            assert(s.len() == 1 + seq_tail.len());
            assert(s.len() > 0);
        },
    }
}

